def find_bridges(n, edges):
    # Build adjacency list
    adj = [set() for _ in range(n + 1)]
    for a, b in edges:
        adj[a].add(b)
        adj[b].add(a)

    def dfs(u, visited, parent):
        visited[u] = True
        low = disc[u] = time_counter
        time_counter += 1

        for v in adj[u]:
            if v == parent:
                continue
            if not visited[v]:
                dfs(v, visited, u)
                low[u] = min(low[u], disc[v])
            else:
                low[u] = min(low[u], disc[v])

        return low[u]

    # Tarjan's algorithm to find bridges
    disc = [float('inf')] * (n + 1)
    low = [0] * (n + 1)
    visited = [False] * (n + 1)
    time_counter = 0
    bridges = []

    def tarjan_bridge(u, parent):
        nonlocal time_counter
        visited[u] = True
        disc[u] = low[u] = time_counter
        time_counter += 1

        for v in adj[u]:
            if v == parent:
                continue
            if not visited[v]:
                tarjan_bridge(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.append((min(u, v), max(u, v)))
            else:
                low[u] = min(low[u], disc[v])

    # Run Tarjan's algorithm for all nodes
    for i in range(1, n + 1):
        if not visited[i]:
            tarjan_bridge(i, -1)

    # Count the number of unique bridges
    bridge_set = set()
    for a, b in bridges:
        bridge_set.add((min(a, b), max(a, b)))

    return len(bridge_set)

