        freq = {}
        for color in arr:
            freq[color] = freq.get(color, 0) + 1
        return freq

    # Try each prefix length from 1 to n
    max_x = 0

    for x in range(1, n + 1):
        prefix = u[:x]
        freq = get_frequencies(prefix)

        # Try removing each day one by one
        can_make_equal = False

        for remove_idx in range(x):
            # Create prefix without remove_idx
            new_freq = {}
            for i in range(x):
                if i != remove_idx:
                    color = prefix[i]
                    new_freq[color] = new_freq.get(color, 0) + 1

            # Check if all remaining colors have the same frequency
            if len(new_freq) == 0:
                # After removing all elements, we have 0 elements — vacuously true
                can_make_equal = True
                break

            # Get all frequencies
            freqs = list(new_freq.values())
            if len(set(freqs)) == 1:
                can_make_equal = True
                break

        if can_make_equal:
            max_x = x

    return max_x

